mapper.select:
SELECT id, doc_id, kb_id, chunk_index, content, heading_path, parent_title, start_page, end_page, token_count, collection_type, course_id, metadata_json, milvus_pk, parent_chunk_id, prev_chunk_id, next_chunk_id, char_offset_start, char_offset_end, correction_status, dense_vector, deleted, created_at, updated_at FROM document_chunk WHERE deleted = 0
AND doc_id = #{docId}
AND kb_id = #{kbId}
AND correction_status = 'PENDING'
AND doc_id IN (SELECT id FROM document WHERE deleted = 0 AND created_by = #{userId}) ORDER BY chunk_index
